package network.restApi.requests

import kotpref.DelayedActionExecutor
import kotpref.eventBus.BanAccountPermanent
import kotpref.eventBus.BlockAccountByVerification
import kotpref.eventBus.RefreshTokenEvent
import kotpref.logging.LogLvl
import kotpref.models.EDialogType
import kotpref.models.ResponseError
import network.restApi.NetworkSession
import io.ktor.client.statement.HttpResponse
import kotpref.eventBus.EventBusManager
import kotpref.eventBus.FacebookTokenError
import network.KtorClient

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-18.
 */
class ResponseCallback<T : Any?>(
    private val networkSession: NetworkSession,
    private val onSuccess: (T?) -> Unit,
    private val onError: () -> Unit = {},
    private var showErrorMessage: Boolean = true,
    private val onErrorWithMessage: (String?) -> Unit = {}
) {

    var successCallback: () -> Unit = {}
    var errorCallback: () -> Unit = {}
    var errorRetryCallback: (() -> Unit)? = null

    companion object {
        var showBlockVerificationPage = false
        var isOnline = true
        var callRetriesForNotValidTokens = false
        var startRefreshToken = false
        var hadFacebookError = false
        private var retryCounters = mutableMapOf<String, Int>()

        fun clearRetryCounters() {
            retryCounters.clear()
        }

        private val delayedActionExecutor = DelayedActionExecutor(1000) {
            //RequestQueue().resumeQueue()
            KtorClient.resumeQueue()
        }
    }

    fun onResponse(result: T) {
        retryCounters.clear()
        isOnline = true
//        val error = response.body()
//        if (error.code != 0) {
//        if (checkError(response.body())) return
        onSuccess(result)
        successCallback()
    }

    fun onFailure(url: String, t: Throwable, response: HttpResponse?) {
        val hasInternet = networkSession.hasInternetConnection()
        var message = t.message ?: ""
        val poorInternetError =
            "Poor internet connection"//AppRes.string.error_message_poor_internet_text
        val noInternetError = "No internet connection"//AppRes.string.error_message_no_internet_text
        val unableToResolve =
            "Unable to resolve host"//AppRes.string.error_message_unable_to_resolve_host_text
        isOnline = false

        val retryCounter = retryCounters[url] ?: 0
        if (errorRetryCallback != null && retryCounter < 10 && (retryCounter < 3 || message.lowercase()
                .contains(unableToResolve)
                    || message.lowercase().contains("handshake") || message.contains("timeout"))
        ) {
            errorRetryCallback?.let { it() }
            val retry: Int = if (retryCounter < 5) retryCounter else 5
            val time: Int = if (retryCounter == 0) 1 else retry * 2
            delayedActionExecutor.start(time.toLong() * 1000)
            networkSession.getLogger().log(
                LogLvl.ERROR, "OkHttp",
                "onFailure url: $url; retryCount: $retryCounter; message: $message"
            )
            retryCounters[url] = retryCounter + 1
            return
        }

        if (!hasInternet) {
            if (networkSession.getAppKeys().userToken.isEmpty() && !networkSession.getAppKeys().userRegistered) {
                networkSession.showMessage(noInternetError)
            } else if (message.lowercase().contains(unableToResolve)) {
                if (showErrorMessage) networkSession.showMessage(poorInternetError)
            } else if (showErrorMessage) networkSession.showMessage(poorInternetError)
            onErrorWithMessage(poorInternetError)
        } else {
            if (message.lowercase().contains("handshake")) {
                networkSession.showMessage(poorInternetError)
            } else if (message.lowercase().contains(unableToResolve)) {
                if (showErrorMessage) networkSession.showMessage(poorInternetError)
            } else if (showErrorMessage && (response?.status?.value ?: 0) >= 500)
                networkSession.showMessage(poorInternetError)
            onErrorWithMessage("")
        }
        onError()
        errorCallback()
    }

    fun onError(url: String, responseError: ResponseError?) {
        var title = "Warning"//AppRes.string.error_message_warning_title
        val error = responseError?.serverErrors?.get(0)
        if (error == null) {
            onErrorWithMessage("")
            onError()
            errorCallback()
            return
        }
        val retryCounter = retryCounters[url] ?: 0
        var message = try {
            if (error.code == 102100 && !hadFacebookError) {
                hadFacebookError = true
                EventBusManager.post(FacebookTokenError())
                return
            }
            if (error.code == 107002 || error.code == 101000) {
                networkSession.getAppKeys().userSubscribeOtherAccount = true
                onErrorWithMessage(error.description)
                errorCallback()
                return
            }
            if (error.code == -1) return
            if (errorRetryCallback != null && (error.baseCode ?: 0) >= 500 && retryCounter < 3) {
                retry(url, retryCounter)
                return
            }
            if (error.baseCode == 502 || error.baseCode == 504 || (error.baseCode == 503 && error.code == 503)) {
                networkSession.showMessage(
                    EDialogType.DIALOG_MAINTENANCE, callback = { KtorClient.resumeQueue() })
                onError()
                onErrorWithMessage(error.description)
                if (retryCounter < 3 && errorRetryCallback != null) retry(url, retryCounter)
                else errorCallback()
                return
            }
            if (error.code == 909707 || error.code == 100012) {
                showBlockVerificationPage = true
                EventBusManager.post(BlockAccountByVerification())
                onError()
                return
            }
            if (error.code == 100006) return
            if (error.code == 110003 || error.code == 100004 || (error.code == 102038 && callRetriesForNotValidTokens)) {
                if (callRetriesForNotValidTokens && retryCounter < 8 && error.code != 110003) {
                    retry(url, retryCounter)
                } else {
                    networkSession.showMessage(error.description, title, onCancel = {
                        networkSession.clearData("code=${error.code}")
                    }, isLastDialog = true)
                    errorCallback()
                }
                return
            }
            if (error.code == 100003 || error.code == 100000 || error.code == 100002) {
                if (url.contains("/auth/refresh")) {
                    networkSession.getLogger().log(
                        LogLvl.ERROR, "OkHttp",
                        "onError url: $url; refresh token not valid"
                    )
                    networkSession.clearData("refresh_code=${error.code}")
                    return
                }
                if (!startRefreshToken) {
                    startRefreshToken = true
                    EventBusManager.post(RefreshTokenEvent())
                }
                if (retryCounter < 3 && errorRetryCallback != null)
                    retry(url, retryCounter, startRetry = false)
                else errorCallback()
                return
            }
            if (error.code == 909606) {
                EventBusManager.post(BanAccountPermanent())
                return
            }
            if (error.code == 105007 || error.code == 105101 || error.code == 105102) {
                onErrorWithMessage("${error.code}")
                onError()
                return
            }
            if (error.baseCode == 500) title =
                "Error"//AppRes.string.error_message_error_title
            error.description
        } catch (e: Throwable) {
            e.message
        }
        var errorText =
            "Unable to resolve host"//AppRes.string.error_message_unable_to_resolve_host_text
        if (message?.contains(errorText, true) == true) {
            if (errorUnableToResolve(url, error.baseCode)) return
            else message =
                "Poor internet connection"//AppRes.string.error_message_poor_internet_text
        }

        errorText = "Error"//AppRes.string.error_message_converted_to_json
        if (message?.contains(errorText, true) == true) showErrorMessage = false

        retryCounters[url] = 0

        if (showErrorMessage) networkSession.showMessage(message, title)
        onErrorWithMessage(message)
        onError()
        errorCallback()
    }

    private fun retry(url: String, retryCounter: Int, startRetry: Boolean = true) {
        errorRetryCallback?.let { it() }
        if (startRetry) {
            val time = if (retryCounter == 0) 1000L else retryCounter * 2000L
            retryCounters[url] = retryCounter + 1
            delayedActionExecutor.start(time)
        }
    }

    private fun errorUnableToResolve(url: String, baseCode: Int?): Boolean {
        val retryCounter = retryCounters[url] ?: 0
        if (retryCounter < 3 && errorRetryCallback != null) {
            if (retryCounter == 0) networkSession.resetRetrofitClient()
            showErrorMessage = false
            networkSession.getLogger().log(
                LogLvl.ERROR, "OkHttp",
                "onError url: $url; retryCount: $retryCounter"
            )
            if ((baseCode ?: 0) >= 500) retry(url, retryCounter)
            return true
        }
        return false
    }
}