package kotpref.models.typeConverter

import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.encodeToJsonElement
import kotlinx.serialization.json.jsonObject


/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-16.
 */
class JsonObjectConverter {
    companion object {

        @OptIn(ExperimentalSerializationApi::class)
        val json = Json {
            isLenient = true; ignoreUnknownKeys = true; explicitNulls = false; encodeDefaults = true
        }

        fun stringToJson(data: String?): JsonObject? {
            if (data.isNullOrEmpty() || data == "null") return null
            val jsonObject = json.parseToJsonElement(data).jsonObject
            return jsonObject
        }

        fun jsonToString(list: JsonObject?): String? {
            if (list == null) return null
            return list.toString()
        }

        inline fun <reified T> stringToObject(data: String?): T? {
            if (data.isNullOrEmpty() || data == "null") return null
            return json.decodeFromString<T>(data)
        }

        inline fun <reified T : Any> objectToString(list: T?): String? {
            return list?.let { json.encodeToJsonElement(it).toString() }
        }

        inline fun <reified T> jsonObjectToObject(data: String?): T? {
            if (data.isNullOrEmpty() || data == "null") return null
            return json.decodeFromString<T>(data)
        }
    }
}