package kotpref.models.account

import kotlinx.serialization.SerialName
import kotlinx.serialization.Transient

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-11.
 */
//@Entity
@kotlinx.serialization.Serializable
data class AccountFilterCompatibilities(
    @Transient
    var useDefaultValues: Boolean = false,

    @SerialName("average_min")
    var averageMin: Int = 0,
    @SerialName("average_max")
    var averageMax: Int = 100,

    @SerialName("goals_min")
    var goalsMin: Int = 0,
    @SerialName("goals_max")
    var goalsMax: Int = 100,

    @SerialName("lifestyle_min")
    var lifestyleMin: Int = 0,
    @SerialName("lifestyle_max")
    var lifestyleMax: Int = 100,

    @SerialName("habits_min")
    var habitsMin: Int = 0,
    @SerialName("habits_max")
    var habitsMax: Int = 100,

    @SerialName("mindset_min")
    var mindsetMin: Int = 0,
    @SerialName("mindset_max")
    var mindsetMax: Int = 100,

    @SerialName("sexual_min")
    var sexualMin: Int = 0,
    @SerialName("sexual_max")
    var sexualMax: Int = 100
) {
    fun calculateAverageMin(): Int {
        val average = (goalsMin + lifestyleMin + mindsetMin + sexualMin + habitsMin) / 5.0
        return roundValue(average)
    }

    fun calculateAverageMax(): Int {
        val average = (goalsMax + lifestyleMax + mindsetMax + sexualMax + habitsMax) / 5.0
        return roundValue(average)
    }

    private fun roundValue(value: Double): Int {
        val diff = (value * 10 % 10) / 10.0
        val final = if (diff >= 0.5) value + (1.0 - diff) else value
        return final.toInt()
    }

    fun isEquals(other: AccountFilterCompatibilities): Boolean {
        return other.averageMin == averageMin &&
                other.averageMax == averageMax &&
                other.goalsMin == goalsMin &&
                other.goalsMax == goalsMax &&
                other.lifestyleMin == lifestyleMin &&
                other.lifestyleMax == lifestyleMax &&
                other.habitsMin == habitsMin &&
                other.habitsMax == habitsMax &&
                other.mindsetMin == mindsetMin &&
                other.mindsetMax == mindsetMax &&
                other.sexualMin == sexualMin &&
                other.sexualMax == sexualMax
    }
}