package kotpref.models.paywall

import kotpref.models.SettingsDefaultCompatibility
import kotpref.models.SettingsEmulatorAttributes
import kotlinx.serialization.SerialName
import kotpref.models.AppVariant

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 27.03.2023.
 */
@kotlinx.serialization.Serializable
data class AdaptySettingsConfig(

    @SerialName("stop_words")
    val stopWords: MutableList<String>? = null,

    @SerialName("default_compatibility_values")
    val defaultCompatibilityValues: SettingsDefaultCompatibility? = null,

    @SerialName("verify_after_android")
    val verifyAfterAndroid: String? = null,

    @SerialName("verify_after_ios")
    val verifyAfterIos: String? = null,

    @SerialName("android_promo_end")
    val androidPromoEnd: String? = null,

    @SerialName("ios_promo_end")
    val iosPromoEnd: String? = null,

    @SerialName("people_screen_type")
    private val peopleScreenType: Int? = null,

    @SerialName("people_screen_swipes_priority")
    val peopleScreenSwipesPriority: Boolean? = null,

    @SerialName("people_screen_block_default")
    val peopleScreenBlockDefault: Boolean? = null,

    @SerialName("show_swipes_instruction")
    val showSwipesInstruction: Boolean? = null,

    @SerialName("emulator_attributes")
    val emulatorAttributes: SettingsEmulatorAttributes? = null,

    @SerialName("settings_feedback_show")
    private val settingsFeedbackShow: Boolean? = null,

    @SerialName("settings_for_apple_review")
    private val settingsForAppleReview: Boolean? = null,

    @SerialName("email_verification_time")
    val emailVerificationTime: Int? = null,
) {
    fun getPeopleScreenType(): Int? {
        return if (AppVariant.isTestBuild()) peopleScreenType else peopleScreenType
    }

    fun getSettingsForAppleReview(): Boolean? {
        return if (AppVariant.isTestBuild()) settingsForAppleReview else settingsForAppleReview
    }

    fun getSettingsFeedbackShow(): Boolean? {
        return if (AppVariant.isTestBuild()) settingsFeedbackShow else settingsFeedbackShow
    }
}