@Composable
fun AdjustViewBoundsImage(
    drawableId: DrawableResource,
    modifier: Modifier = Modifier,
    tintColor: Color? = null,
    contentDescription: String? = null
) {
    val painter = painterResource(drawableId)
    val imageRatio = painter.intrinsicSize.width / painter.intrinsicSize.height
    if (imageRatio <= 0) return
    val colorFilter = tintColor?.let { ColorFilter.tint(it) }
    Image(
        painter = painter,
        contentDescription = contentDescription,
        modifier = modifier.aspectRatio(imageRatio),
        colorFilter = colorFilter
    )
}

@Composable
fun ImageByContainerSize(
    drawableId: DrawableResource,
    modifier: Modifier = Modifier,
    tintColor: Color? = null,
    contentDescription: String? = null
) {
    BoxWithConstraints(modifier = modifier) {
        val maxWidthPx = constraints.maxWidth.toFloat()
        val maxHeightPx = constraints.maxHeight.toFloat()

        val painter = painterResource(drawableId)
        val intrinsicSize = painter.intrinsicSize

        if (intrinsicSize.width <= 0f || intrinsicSize.height <= 0f) return@BoxWithConstraints

        val imageRatio = intrinsicSize.width / intrinsicSize.height

        val targetWidth: Float
        val targetHeight: Float

        if (maxWidthPx / imageRatio <= maxHeightPx) {
            targetWidth = maxWidthPx
            targetHeight = maxWidthPx / imageRatio
        } else {
            targetHeight = maxHeightPx
            targetWidth = maxHeightPx * imageRatio
        }

        val colorFilter = tintColor?.let { ColorFilter.tint(it) }

        Image(
            painter = painter,
            contentDescription = contentDescription,
            modifier = Modifier
                .width(targetWidth.dp)
                .height(targetHeight.dp)
                .align(Alignment.Center),
            colorFilter = colorFilter
        )
    }
}


@Composable
fun ImageView(
    drawableId: DrawableResource,
    modifier: Modifier = Modifier,
    tintColor: Color? = null,
    contentDescription: String? = null,
    scaleType: ContentScale = ContentScale.Crop
) {
    val painter = painterResource(drawableId)
    val colorFilter = tintColor?.let { ColorFilter.tint(it) }
    Image(
        painter = painter,
        contentDescription = contentDescription,
        modifier = modifier,
        colorFilter = colorFilter,
        contentScale = scaleType
    )
}

@Composable
fun ImageView(
    url: String?,
    placeholder: DrawableResource? = null,
    modifier: Modifier = Modifier,
    tintColor: Color? = null,
    contentDescription: String? = null,
    scaleType: ContentScale = ContentScale.Crop
) {
    val painter = if (!url.isNullOrEmpty()) {
        val placeholderPainter: (@Composable () -> Painter)? =
            placeholder?.let { { painterResource(it) } }

        rememberImagePainter(url, placeholderPainter = placeholderPainter)
    } else if (placeholder != null) {
        painterResource(placeholder)
    } else return
    val colorFilter = tintColor?.let { ColorFilter.tint(it) }
    Image(
        painter = painter,
        contentDescription = contentDescription,
        modifier = modifier,
        colorFilter = colorFilter,
        contentScale = scaleType
    )
}

