@Composable
fun PreloadProcessor() {
    val currentResourceToProcess by ImagePreloaderQueue.currentResourceToProcess.collectAsState()

    val activeResource = currentResourceToProcess
    if (activeResource != null) {
        val loadedPainter = painterResource(activeResource)
        SideEffect {
            ImagePreloaderQueue.completeCurrentPreload(activeResource)
        }
    }
}

object ImagePreloaderQueue {
    private var queue = emptyList<DrawableResource>()

    private val _currentResourceToProcess = MutableStateFlow<DrawableResource?>(null)
    val currentResourceToProcess = _currentResourceToProcess.asStateFlow()

    fun addToQueue(resource: DrawableResource) {
        if (resource !in this.queue) {
            val newList = queue + resource
            if (queue.isEmpty()) {
                _currentResourceToProcess.value = newList.firstOrNull()
            }
            queue = newList
        }
    }

    fun addToQueue(resources: List<DrawableResource>) {
        val newRes = resources.filter { !queue.contains(it) }
        if (newRes.isNotEmpty()) {
            val newList = queue + newRes
            _currentResourceToProcess.value = newList.firstOrNull()
            queue = newList
        }
    }

    fun completeCurrentPreload(resource: DrawableResource) {
        val newList = queue.toMutableList()
        if (newList.firstOrNull() == resource) {
            newList.removeAt(0)
        }
        _currentResourceToProcess.value = newList.firstOrNull()
        queue = newList
    }
}