@Composable
fun JsImageView(
    drawableId: String,
    modifier: Modifier = Modifier,
    format: String = "png",
    contentScale: ContentScale = ContentScale.Crop,
    tintColor: Color? = null,
) {
    val objectFit = when (contentScale) {
        ContentScale.Fit -> "contain"
        ContentScale.FillBounds -> "fill"
        ContentScale.FillWidth -> "fill"
        ContentScale.Crop -> "cover"
        ContentScale.None -> "none"
        else -> "none"
    }

    val objectPosition = when (contentScale) {
        ContentScale.FillWidth -> "top"
        else -> "center"
    }

    if (drawableId.isEmpty()) Box(modifier = modifier)
    else Image(
        src = "images/$drawableId.$format",
        modifier = modifier.styleModifier {
            property("object-fit", objectFit)
            property("object-position", objectPosition)
            if (tintColor != null) {
                color(tintColor)
            }
        }
    )
}

@Composable
fun JsImageView(
    drawableRes: DrawableResource?,
    modifier: Modifier = Modifier,
    format: String = "png",
    contentScale: ContentScale = ContentScale.Crop,
    tintColor: Color? = null,
) {
    val drawableId = drawableRes?.getDrawableIdName() ?: ""
    JsImageView(drawableId, modifier, format, contentScale, tintColor)
}


@Composable
fun PreloadProcessor() {
    val currentResourceToProcess by ImagePreloaderQueue.currentResourceToProcess.collectAsState()
    val activeResource = currentResourceToProcess
    if (activeResource != null) {
        JsImageView(activeResource, Modifier.size(0.px))
        LaunchedEffect(activeResource) {
            delay(300)
            ImagePreloaderQueue.completeCurrentPreload(activeResource)
        }
    }
}

object ImagePreloaderQueue {
    private var queue = emptyList<String>()

    private val _currentResourceToProcess = MutableStateFlow<String?>(null)
    val currentResourceToProcess = _currentResourceToProcess.asStateFlow()

    fun addToQueue(resource: String) {
        if (resource !in this.queue) {
            val newList = queue + resource
            if (queue.isEmpty()) {
                _currentResourceToProcess.value = newList.firstOrNull()
            }
            queue = newList
        }
    }

    fun addToQueue(resources: List<String>) {
        val newRes = resources.filter { !queue.contains(it) }
        if (newRes.isNotEmpty()) {
            val newList = queue + newRes
            _currentResourceToProcess.value = newList.firstOrNull()
            queue = newList
        }
    }

    fun completeCurrentPreload(resource: String) {
        val newList = queue.toMutableList()
        if (newList.firstOrNull() == resource) {
            newList.removeAt(0)
        }
        _currentResourceToProcess.value = newList.firstOrNull()
        queue = newList
    }
}