    private fun webSocketSend(json: String?, event: String) {
        networkSession.webSocketSend(json, event)
    }

    fun sendWow(userId: Id, onSuccess: (String?) -> Unit, onError: (String?) -> Unit) {
        if (userId.isEmpty()) {
            onSuccess(null)
            return
        }
        val event = SocketEvent.Wow
        addCallbacks(event, onSuccess, onError)
        val socket = SocketWowBody(
            event.event, SocketWow(userId.toInt()), Endpoint.version
        )
        webSocketSend(JsonObjectConverter.objectToString(socket), event.event)
    }

    fun sendMessage(
        chatId: Int, messageItem: ChatMessageItem?,
        onSuccess: (String?) -> Unit, onError: (String?) -> Unit
    ) {
        val event = SocketEvent.Message
        addCallbacks(event, onSuccess, onError)
        val type = messageItem?.type ?: 1
        val message =
            if (messageItem?.type == 1) messageItem.getText() ?: "" else messageItem?.imageUrl ?: ""
        val lifetime = messageItem?.image?.lifetime
        val socket = SocketMessageBody(
            event.event,
            SocketMessage(messageItem?.getId() ?: "", chatId, type, message, lifetime),
            Endpoint.version
        )
        webSocketSend(JsonObjectConverter.objectToString(socket), event.event)
    }

    fun sendGiftMessage(
        giftId: String, userId: Int, chatId: Int?, messageId: String, transactionId: String,
        onSuccess: (String?) -> Unit, onError: (String?) -> Unit
    ) {
        val event = SocketEvent.Gift
        addCallbacks(event, onSuccess, onError)
        val socket = SocketMessageGiftBody(
            event.event,
            SocketGift(messageId, userId, chatId, transactionId, giftId),
            Endpoint.version
        )
        webSocketSend(JsonObjectConverter.objectToString(socket), event.event)
    }

    fun startTyping(chatId: String, type: Int, accountId: String, isStart: Boolean) {
        if (chatId.isEmpty() || accountId.isEmpty()) return
        val event = SocketEvent.CreatingMessage.event
        val socket = SocketStartMessageBody(
            event, SocketStartMessage(
                chatId.toInt(), type, accountId.toInt(), if (isStart) "start" else "end"
            ), Endpoint.version
        )
        webSocketSend(JsonObjectConverter.objectToString(socket), event)
    }

