    fun subscribe(userIds: MutableList<Id>) {
        val event = SocketEvent.Subscribe.event
        val socket = SocketSubscribeBody(
            event,
            SocketSubscribeData(userIds.filter { it.isNotEmpty() }.map { it.toInt() }
