    }

    fun createRequest(
        recipientId: String, messageItem: ChatMessageItem?,
        onSuccess: (String?) -> Unit, onError: (String?) -> Unit
    ) {
        if (recipientId.isEmpty()) return
        val event = SocketEvent.CreateRequest
        addCallbacks(event, onSuccess, onError)
        val type = messageItem?.type ?: 1
        val message =
            if (messageItem?.type == 1) messageItem.getText() ?: "" else messageItem?.imageUrl ?: ""
        val body = SocketRequest(
            recipientId.toInt(), message, messageItem?.getId(), type, messageItem?.image?.lifetime
        )
        val socket = SocketRequestBody(event.event, body, Endpoint.version)
        webSocketSend(JsonObjectConverter.objectToString(socket), event.event)
    }

    fun deleteAccount(onSuccess: (String?) -> Unit, onError: (String?) -> Unit) {
        if (isClose) {
            onSuccess(null)
            return
        }
        val event = SocketEvent.AccountDelete
        addCallbacks(event, onSuccess, onError)
        val socket = SocketEventBody(event.event, Endpoint.version)
        webSocketSend(JsonObjectConverter.objectToString(socket), event.event)

        onSuccess(null)
    }

