    fun loadHistory(
        chatId: Int, myAccountId: String, limit: Int, offset: Int,
        onSuccess: (MessageList?) -> Unit, onError: () -> Unit = {}
    ) {
        val url = "$chatUrl/chats/${chatId}"
        val params = "?limit=$limit&offset=$offset"
        ktorClient.getOrDeleteInfo(
            url + params, getToken(),
            responseCallback = ResponseCallback<ChatHistory?>(networkSession, onSuccess = {
                val messages = mutableListOf<String>()
                val unreadMessages = mutableListOf<String>()
                it?.data?.history?.forEach { message ->
                    messages.add(message.uuid)
                    if (!message.isRead && message.sender != myAccountId) unreadMessages.add(message.uuid)
                }
                networkSession.readMessages(chatId, unreadMessages)
                onSuccess(it?.data)
            }, onError = onError, showErrorMessage = false)
        )
        /*val call = { chatApi.loadChatHistory(chatId, getToken(), limit, offset) }
        val callback = ResponseCallback<ChatHistory?>(networkSession, onSuccess = {
