    fun sentPhotoChat(
        filePath: String, //listener: ProgressRequestBody.UploadCallbacks? = null,
        onSuccess: (AccountMessagePhotoBody?) -> Unit, onError: () -> Unit = {}
    ) {
        val file = filePath.replace("file://", "")
        val resultFile = imageUtils.getResultFileSendToServer(file, onError) ?: return

        val body = formData {
            append(
                "photo", resultFile.bytes,
                Headers.build {
                    append(HttpHeaders.ContentType, "image/jpeg")
                    append(HttpHeaders.ContentDisposition, "filename=${resultFile.name}")
                })
        }

        val url = "$chatUrl/photos"
        ktorClient.multipart(
            url, body, getToken(),
            responseCallback = ResponseCallback(networkSession, onSuccess, onError)
        )
        /*val call = { chatApi.sendPhoto(body, getToken()) }
        RequestQueue().callRequest(call, (ResponseCallback(networkSession, onSuccess, onError)))*/
    }

