package network

import io.ktor.client.HttpClient
import io.ktor.client.plugins.HttpTimeout
import io.ktor.client.plugins.HttpTimeoutConfig
import io.ktor.client.plugins.contentnegotiation.ContentNegotiation
import io.ktor.client.plugins.defaultRequest
import io.ktor.client.plugins.websocket.WebSockets
import io.ktor.client.request.header
import io.ktor.http.ContentType
import io.ktor.http.contentType
import io.ktor.serialization.kotlinx.json.json
import kotlinx.serialization.json.Json

@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
actual class HttpClient actual constructor() {
    actual fun buildOkHttpClient(userAgent: String, language: () -> String): HttpClient {
        val okHttpClient = HttpClient {
            install(ContentNegotiation) {
                json(Json {
                    isLenient = true; ignoreUnknownKeys = true; explicitNulls =
                    false; encodeDefaults = true
                })
            }
            install(HttpTimeout) {
                requestTimeoutMillis = 30 * 1000L
                connectTimeoutMillis = HttpTimeoutConfig.INFINITE_TIMEOUT_MS
                socketTimeoutMillis = 5 * 60 * 1000L
            }

            install(WebSockets) {
                pingIntervalMillis = 5 * 1000
                maxFrameSize = Long.MAX_VALUE
            }

            defaultRequest {
                header("User-Agent", userAgent)
                header("Accept-Language", language())

                contentType(ContentType.Application.Json)
            }
        }
        return okHttpClient
    }

}