let widgetId = null;

export function setupRecaptcha(containerId, siteKey) {
    ensureRecaptchaReady(() => {
        const container = document.getElementById(containerId);
        if (!container) {
            widgetId = null;
            return;
        }

        if (widgetId === null || !container.hasAttribute('data-recaptcha-id') || container.getAttribute('data-recaptcha-id') !== String(widgetId)) {

            if (widgetId !== null) {
                while (container.firstChild) {
                    container.removeChild(container.firstChild);
                }
            }

            widgetId = grecaptcha.render(container, {
                sitekey: siteKey,
                size: "invisible",
                callback: function(token) {
                    if (window.__recaptchaCallback) {
                        window.__recaptchaCallback(token);
                    }
                }
            });
            container.setAttribute('data-recaptcha-id', widgetId);
        } else {
            grecaptcha.reset(widgetId);
        }

        grecaptcha.execute(widgetId);
    });
}

export function resetRecaptchaWidget() {
    console.log("Recaptcha: resetRecaptchaWidget called. Setting widgetId to null.");
    widgetId = null;
}

export function ensureRecaptchaReady(callback) {
    if (typeof grecaptcha !== 'undefined' && grecaptcha.render) {
        callback();
    } else {
        const interval = setInterval(() => {
            if (typeof grecaptcha !== 'undefined' && grecaptcha.render) {
                clearInterval(interval);
                callback();
            }
        }, 100);
    }
}

export function initRecaptchaCallback(callback) {
    window.__recaptchaCallback = function(token) {
        callback(token)
    };
}
