enum class JsSplashSignUpScreenState { START, NICKNAME, BIRTHDAY }

@Composable
fun JsSplashSignUpScreen(
    obtainEvent: (SplashSignUpAboutEvent) -> Unit,
) {
    val currentState = remember { mutableStateOf(JsSplashSignUpScreenState.START) }

    val viewModel =
        rememberJsViewModel { SplashSignUpAboutVM(AuthorizationType.EMAIL.name, null, obtainEvent) }


    PageColumnContainer {
        JsCustomTabBar(
            onBack = {
                when (currentState.value) {
                    JsSplashSignUpScreenState.BIRTHDAY -> currentState.value =
                        JsSplashSignUpScreenState.NICKNAME

                    JsSplashSignUpScreenState.NICKNAME -> currentState.value =
                        JsSplashSignUpScreenState.START

                    else -> viewModel.back()
                }
            },
            withBackground = false
        )

        when (currentState.value) {
            JsSplashSignUpScreenState.START -> {
                Box(modifier = Modifier.weight(0.6f).minHeight(24.dp))
                SignUpStartState(viewModel)
                Box(modifier = Modifier.weight(1.4f).minHeight(24.dp))
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 24.dp),
                    horizontalArrangement = Arrangement.Center
                ) {
                    JsTextView(
                        text = stringResource(Res.string.auth_start_group_text_sign_in),
                        textColor = JsMainTheme.colors.text_color_gray,
                        textSize = 15,
                        fontWeight = FontWeight.Medium,
                        textAlign = TextAlign.Center
                    )
                    JsTextView(
                        text = stringResource(Res.string.auth_sign_in),
                        modifier = Modifier
                            .padding(leftRight = 16.dp)
                            .onClick {
                                obtainEvent(
                                    SplashSignUpAboutEvent.SplashSignInEmail(
                                        AuthorizationType.EMAIL,
                                        viewModel.passwordValue.value,
                                        viewModel.emailValue.value.text,
                                    )
                                )
                            },
                        textColor = JsMainTheme.colors.app_main_color,
                        textSize = 15,
                        fontWeight = FontWeight.Medium,
                        textAlign = TextAlign.Center
                    )
                }
            }

            JsSplashSignUpScreenState.NICKNAME -> {
                Box(modifier = Modifier.weight(0.3f).minHeight(24.dp))
                SignUpNicknameState(viewModel)
                Box(modifier = Modifier.weight(1.7f).minHeight(24.dp))
            }

            JsSplashSignUpScreenState.BIRTHDAY -> {
                Box(modifier = Modifier.weight(0.4f).minHeight(24.dp))
                SignUpBirthdayState(viewModel)
                Box(modifier = Modifier.weight(1.6f).minHeight(24.dp))
            }
        }

        Box(
            Modifier.fillMaxWidth().padding(bottom = 26.dp),
            contentAlignment = Alignment.Center
        ) {
            val displayNameErrorText =
                stringResource(Res.string.auth_sign_in_incorrect_display_name)
            val birthdayErrorText = stringResource(Res.string.pick_date_age_less_18_text)

            val emailErrorText = stringResource(Res.string.auth_sign_in_incorrect_email)
            val passwordErrorText = stringResource(Res.string.error_message_sign_password_at_least)

            SplashFiorryButton(
                title = stringResource(Res.string.onboarding_start_btn_text_next),
                onDoubleTap = {
                    //if (AppVariant.isWeb() && AppVariant.isDebug()) onClick(true)
                }
            ) {
                when (currentState.value) {
                    JsSplashSignUpScreenState.START -> {
                        val emailError = viewModel.checkEmailError(emailErrorText)
                        val passwordError = viewModel.checkPasswordError(passwordErrorText)
                        if (emailError || passwordError) return@SplashFiorryButton
                        currentState.value = JsSplashSignUpScreenState.NICKNAME
                    }

                    JsSplashSignUpScreenState.NICKNAME -> {
                        val displayNameError = viewModel.checkDisplayNameError(displayNameErrorText)
                        if (displayNameError) return@SplashFiorryButton
                        currentState.value = JsSplashSignUpScreenState.BIRTHDAY
                    }

                    else -> {
                        val birthdayError = viewModel.checkBirthdayError(birthdayErrorText)
                        if (birthdayError) return@SplashFiorryButton
                        viewModel.createAccount()
                    }
                }
            }
        }
    }

    JsAnimatedVisibility(visible = viewModel.showBirthdayPicker.value, durationMs = 500) {
        Box(
            Modifier.fillMaxSize()
                .background(color = JsMainTheme.colors.main_color_black_transparent_70)
                .onClick { viewModel.showBirthdayPicker.value = false }
        ) {
            val months = shortMonthsList()
            JsDatePickerBottomSheet(
                modifier = Modifier.align(Alignment.BottomCenter),
                doneLabel = stringResource(Res.string.nav_settings_done),
                startDate = viewModel.birthdayDate,
                onDoneClick = {
                    viewModel.onDoneClickPickerCompose(it, months) {
                        viewModel.showBirthdayPicker.value = false
                    }
                },
            )
        }
    }

    if (viewModel.showRecaptcha.value) Div(
        attrs = Modifier.fillMaxSize().id(WebContainer.CaptchaScreen.screenName).toAttrs()
    )
}

@Composable
private fun SignUpStartState(viewModel: SplashSignUpAboutVM) {
    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(modifier = Modifier.height(16.dp))

        JsTextView(
            text = stringResource(Res.string.auth_sign_up_title_page),
            modifier = Modifier
                .fillMaxWidth()
                .padding(leftRight = 20.dp),
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 24,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )
        Box(modifier = Modifier.height(32.dp))

        JsOutlinedTextField(
            value = viewModel.emailValueString.value,
            textSize = 14,
            textMinHeight = 50,
            label = stringResource(Res.string.auth_text_hint_email),
            isError = viewModel.emailError.value.isNotEmpty(),
            errorText = viewModel.emailError.value,
            modifier = Modifier.fillMaxWidth(80.percent)
                .onFocusIn { viewModel.hideErrorByField(ErrorField.Email) },
            onValueChange = {
                viewModel.emailValue.value = TextFieldValue(it)
                viewModel.emailValueString.value = it
            }
        )

        var showPassword by remember { mutableStateOf(false) }
        JsOutlinedTextField(
            value = viewModel.passwordValue.value,
            textSize = 14,
            textMinHeight = 50,
            label = stringResource(Res.string.auth_text_hint_password),
            isError = viewModel.passwordError.value.isNotEmpty(),
            errorText = viewModel.passwordError.value,
            modifier = Modifier.fillMaxWidth(80.percent).padding(top = 12.dp)
                .onFocusIn { viewModel.hideErrorByField(ErrorField.Password) },
            inputType = if (showPassword) InputType.Text else InputType.Password,
            rightIcon = if (showPassword) "ic_password_visibility_off_web" else "ic_password_visibility_web",
            rightIconClick = { showPassword = !showPassword },
            onValueChange = {
                viewModel.passwordValue.value = it
            }
        )
    }
}


@Composable
private fun SignUpNicknameState(viewModel: SplashSignUpAboutVM) {
    val nicknameManager: NicknameChangeManager by di.instance()
    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        JsImageView("ic_sign_up_nickname_web", Modifier.fillMaxWidth(50.percent))

        JsTextView(
            text = stringResource(Res.string.sign_up_about_nickname_title),
            modifier = Modifier
                .fillMaxWidth()
                .padding(leftRight = 20.dp, top = 44.dp),
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 24,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )

        JsTextView(
            text = stringResource(Res.string.sign_up_about_nickname_text),
            modifier = Modifier
                .fillMaxWidth()
                .padding(leftRight = 20.dp, topBottom = 32.dp),
            textColor = JsMainTheme.colors.text_color_hint,
            textSize = 16,
            fontWeight = FontWeight.Normal,
            textAlign = TextAlign.Center
        )

        val displayError =
            stringResource(Res.string.auth_sign_in_incorrect_latin_display_name)
        JsOutlinedTextField(
            value = viewModel.nicknameValue.value,
            textSize = 14,
            textMinHeight = 50,
            label = stringResource(Res.string.sign_up_about_nickname_placeholder),
            isError = viewModel.nicknameError.value.isNotEmpty(),
            errorText = viewModel.nicknameError.value,
            modifier = Modifier.fillMaxWidth(80.percent)
                .onFocusIn { viewModel.hideErrorByField(ErrorField.DisplayName) },
            onValueChange = {
                nicknameManager.saveChanges(
                    it, viewModel.nicknameValue.value, callback = { value ->
                        viewModel.nicknameValue.value = value
                    },
                    onError = { viewModel.nicknameError.value = displayError }
                )
            }
        )
    }
}


