            modifier = Modifier
                .fillMaxWidth()
                .padding(leftRight = 20.dp, top = 44.dp),
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 24,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )

        JsTextView(
            text = stringResource(Res.string.sign_up_about_birthday_text),
            modifier = Modifier
                .fillMaxWidth()
                .padding(leftRight = 20.dp, topBottom = 32.dp),
            textColor = JsMainTheme.colors.text_color_hint,
            textSize = 16,
