enum class AppNavigationPage {
    Loading,
    StartScreen,
    OnboardingScreen,
    MainScreen
}

@Serializable
sealed class StartPagesRoute {
    @Serializable
    data object EnterScreen : StartPagesRoute()

    @Serializable
    data object RegisterScreen : StartPagesRoute()

    @Serializable
    data class RegisterEmailScreen(
        val authorizationType: String, val social: String?
    ) : StartPagesRoute()

    @Serializable
    data object LoginScreen : StartPagesRoute()

    @Serializable
    data class LoginEmailScreen(
        val authorizationType: String,
        val email: String = "",
        val password: String = ""
    ) : StartPagesRoute()
}

@Serializable
sealed class OnboardingPagesRoute {
    @Serializable
    data object SelectGenderScreen : OnboardingPagesRoute()

    @Serializable
    data object SelectInterestedGenderScreen : OnboardingPagesRoute()

    @Serializable
    data object AgeScreen : OnboardingPagesRoute()

    @Serializable
    data class Interest(
        val useSelectData: Boolean, val profileDataField: String
    ) : OnboardingPagesRoute()

    @Serializable
    data class PhotosSelect(
        val fromPage: PhotosFromPage
    ) : OnboardingPagesRoute()

    @Serializable
    data object Tutorial : OnboardingPagesRoute()

    @Serializable
    data object Compatibility : OnboardingPagesRoute()

    @Serializable
    data object CompatibilityAnswers : OnboardingPagesRoute()

    @Serializable
    data object Finish : OnboardingPagesRoute()

    @Serializable
    data object Paywall : OnboardingPagesRoute()
}

enum class MainPagesRoute {
    SettingsScreen,
    SettingsEditProfile,
    SettingsChangePassword
}

enum class AppScreenEvent {
    ShowStartPages,
    ShowOnboardingPages,
    ShowMainPages,
}

class AppScreenVM :
    EventsViewModel<AppNavigationPage, AppScreenEvent>(AppNavigationPage.Loading) {

    private val dialogManager: IDialogManager by di.instance()
    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    val appKeys = repositoriesProvider.appKeys

    val className = "AppScreenVM"
    var showDialogState = mutableStateListOf<ShowAlertState>()

    init {
        eventBusManager.addObserver(className, ::onEventBusMessage)
        dialogManager.showDialog = { state ->
            println("dialogManager.showDialog: $state")
            showDialogState.add(state)
        }
        viewModelScope.launch {
            val appKeys = repositoriesProvider.appKeys
            if (appKeys.startOnboarding || AppVariant.isDebug()) {
                setUiState(AppNavigationPage.OnboardingScreen)
            } else {
                setUiState(AppNavigationPage.StartScreen)
            }
        }
    }

    private fun setUiState(state: AppNavigationPage) {
        uiState = state
        eventBusManager.postEvent(BusEvent.ChangeMainScreenState(state.name))
    }

    override fun obtainEvent(event: AppScreenEvent) {
        when (event) {
            AppScreenEvent.ShowStartPages -> setUiState(AppNavigationPage.StartScreen)
            AppScreenEvent.ShowMainPages -> setUiState(AppNavigationPage.MainScreen)
            AppScreenEvent.ShowOnboardingPages -> setUiState(AppNavigationPage.OnboardingScreen)
        }
    }

    override fun onEventBusMessage(event: BusEvent) {
        when (event) {
            //is BusEvent.Logout -> logout()
            else -> {}
        }
    }
}