package web.views.dialog.dialogInfoGender

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.css.FontWeight
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.foundation.layout.Column
import com.varabyte.kobweb.compose.foundation.layout.Row
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.background
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxWidth
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.size
import com.varabyte.kobweb.compose.ui.modifiers.width
import web.helpers.clipByCorner
import web.helpers.dp
import web.helpers.padding
import web.theme.JsMainTheme
import web.views.JsTextView
import web.views.Spacer


@Composable
fun JsInfoGenderItem(
    title: String,
    text: String
) {
    Column(modifier = Modifier.fillMaxWidth().padding(start = 16.dp, end = 16.dp, top = 16.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier.size(8.dp).clipByCorner()
                    .background(color = JsMainTheme.colors.app_main_color)
            )

            Spacer(modifier = Modifier.width(8.dp))
            JsTextView(
                modifier = Modifier.weight(1f), textSize = 14,
                text = title,
                fontWeight = FontWeight.Medium
            )
        }

        Spacer(modifier = Modifier.height(4.dp))

        JsTextView(text = text, textSize = 14)
    }
}