@Composable
fun AutoResizeText(
    modifier: Modifier = Modifier,
    text: String,
    fontSizeRange: FontSizeRange = FontSizeRange(16.sp),
    color: Color = MainTheme.colors.text_color_default,
    fontStyle: FontStyle? = null,
    fontWeight: FontWeight = FontWeight.Normal,
    fontFamily: FontFamily? = null,
    letterSpacing: TextUnit = TextUnit.Unspecified,
    textDecoration: TextDecoration? = null,
    textAlign: TextAlign? = null,
    lineHeight: TextUnit = TextUnit.Unspecified,
    overflow: TextOverflow = TextOverflow.Clip,
    softWrap: Boolean = true,
    maxLines: Int = Int.MAX_VALUE,
    style: TextStyle = LocalTextStyle.current,
    changeFontSizeAfterDrawing: Boolean = true,
    rememberKey: Any? = null
) {
    val fontSizeValue = remember(rememberKey) { mutableStateOf(fontSizeRange.max) }
    val readyToDraw = remember(rememberKey) { mutableStateOf(false) }

    Text(
        text = text,
        color = color,
        maxLines = maxLines,
        fontStyle = fontStyle,
        fontWeight = fontWeight,
        fontFamily = fontFamily,
        letterSpacing = letterSpacing,
        textDecoration = textDecoration,
        textAlign = textAlign,
        lineHeight = lineHeight,
        overflow = overflow,
        softWrap = softWrap,
        style = style,
        fontSize = fontSizeValue.value,
        modifier = modifier.drawWithContent { if (readyToDraw.value) drawContent() },
        onTextLayout = {
            if (readyToDraw.value && fontSizeValue.value != fontSizeRange.max) {
                if (changeFontSizeAfterDrawing) {
                    readyToDraw.value = false
                    fontSizeValue.value = fontSizeRange.max
                }
                return@Text
            }
            if ((it.didOverflowHeight || it.didOverflowWidth)) {
                val nextFontSizeValue = fontSizeValue.value.value - fontSizeRange.step.value
                if (nextFontSizeValue <= fontSizeRange.min.value) {
                    // Reached minimum, set minimum font size and it's readToDraw
                    fontSizeValue.value = fontSizeRange.min
                    readyToDraw.value = true
                } else {
                    // Text doesn't fit yet and haven't reached minimum text range, keep decreasing
                    fontSizeValue.value = nextFontSizeValue.sp
                }
            } else {
                // Text fits before reaching the minimum, it's readyToDraw
                readyToDraw.value = true
            }
        }
    )
}

@Composable
fun DrawLineText(
    modifier: Modifier = Modifier,
    text: String,
    color: Color = MainTheme.colors.app_main_color,
    fontSize: TextUnit = 15.sp,
    fontWeight: FontWeight = FontWeight.Medium,
    textAlign: TextAlign = TextAlign.Center,
    onClick: () -> Unit
){
    Text(
        text = text,
        modifier = modifier.clickable(null) { onClick() }.drawBehind {
            drawLine(
                color = color,
                start = Offset(0f, size.height),
                end = Offset(size.width, size.height),
                strokeWidth = 1.dp.toPx()
            )
        }.padding(top = 24.dp),
        fontSize = fontSize,
        color = color,
        fontWeight = fontWeight,
        textAlign = textAlign,
    )
}

data class FontSizeRange(
    val max: TextUnit,
    val min: TextUnit = 8.sp,
    val step: TextUnit = 1.sp,
) {
    init {
        require(min < max) { "min should be less than max, $this" }
        require(step.value > 0) { "step should be greater than 0, $this" }
    }
}

@Composable
fun CustomClickableText(
    text: AnnotatedString,
    modifier: Modifier = Modifier,
    style: TextStyle = TextStyle.Default,
    softWrap: Boolean = true,
    overflow: TextOverflow = TextOverflow.Clip,
    maxLines: Int = Int.MAX_VALUE,
    onTextLayout: (TextLayoutResult) -> Unit = {},
    onClick: (Int) -> Unit
) {
    val layoutResult = remember { mutableStateOf<TextLayoutResult?>(null) }
    val pressIndicator = Modifier.pointerInput(onClick) {
        detectTapGestures { pos ->
            layoutResult.value?.let { layoutResult ->
                onClick(layoutResult.getOffsetForPosition(pos))
            }
        }
    }

    BasicText(
        text = text,
        modifier = modifier.then(pressIndicator),
        style = style,
        softWrap = softWrap,
        overflow = overflow,
        maxLines = maxLines,
        onTextLayout = {
            layoutResult.value = it
            onTextLayout(it)
        }
    )
}