@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
actual class NicknameChangeManager {

    val maxLength: Int = 15

    actual fun getEmojiCount(charSequence: CharSequence): Int {
        return 0
    }

    actual fun removeAllEmoji(text: CharSequence): String {
        return text.toString()
    }

    actual fun saveChanges(
        text: String,
        lastText: String,
        callback: (String) -> Unit,
        onError: () -> Unit
    ) {
        if (lastText == text) return

        val lastEmojiCount = if (lastText.isEmpty()) 0 else getEmojiCount(lastText)
        val lastTextWithoutEmoji = if (lastText.isEmpty()) "" else removeAllEmoji(lastText)
        val lastTextCount = lastEmojiCount * 3 + lastTextWithoutEmoji.length

        val emojiCount = if (text.isEmpty()) 0 else getEmojiCount(text)
        val textWithoutEmoji = if (text.isEmpty()) "" else removeAllEmoji(text)
        val textWithoutEmojiAndSpaces =
            if (text.isEmpty()) "" else textWithoutEmoji.replace(" ", "")

        val characterFilter = ".*[^\\p{L}0-9 ].*".toRegex()
        /*if (AppVariant.isFiorry()) ".*[^a-zA-Z0-9 ].*".toRegex()
    else  */
        val incorrectText = textWithoutEmojiAndSpaces.matches(characterFilter)
        if (incorrectText) {
            onError()
        } else {
            val textCount = emojiCount * 3 + textWithoutEmoji.length
            if (textCount <= maxLength || textCount < lastTextCount) {
                callback(text)
            }
        }
    }

}