package web.theme

import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.staticCompositionLocalOf
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import ui.theme.ColorMode
import ui.theme.ThemeBundle

object JsMainTheme {
    val colors: ThemeColors
        @Composable
        get() = JsLocalThemeColors.current
}

val JsLocalThemeColors = staticCompositionLocalOf<ThemeColors> {
    error("No colors provided")
}

object JsThemeEventBus {

    private val _currentSettings: MutableStateFlow<ThemeBundle> = MutableStateFlow(
        ThemeBundle(colorMode = ColorMode.DARK, currentLocale = "en")
    )
    val currentSettings: StateFlow<ThemeBundle> = _currentSettings

    fun updateColorMode(newColorMode: ColorMode) {
        _currentSettings.value = currentSettings.value.copy(colorMode = newColorMode)
    }

    fun updateCurrentLocal(currentLocal: String) {
        _currentSettings.value = currentSettings.value.copy(currentLocale = currentLocal)
    }

}


@Composable
fun JsMainAppTheme(
    content: @Composable () -> Unit
) {
    val currentThemeBundle by JsThemeEventBus.currentSettings.collectAsState()
    val colors = when (currentThemeBundle.colorMode) {
        ColorMode.DARK -> baseDarkPalette
        ColorMode.LIGHT -> baseDarkPalette
    }

    CompositionLocalProvider(
        JsLocalThemeColors provides colors,
        content = content
    )
}