@Composable
fun PaywallScreen(
    viewModelCallback: (PaywallScreenEvent) -> Unit,
    viewModel: PaywallScreenVM = viewModel { PaywallScreenVM(viewModelCallback) }
) {
    BackHandler { }

    val colorList = viewModel.colorList.ifEmpty {
        listOf(
            MainTheme.colors.gradient_subscribe_unlim_color_start,
            MainTheme.colors.gradient_subscribe_unlim_color_end
        )
    }

    PageContainer {
        BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
            Box(
                Modifier.fillMaxSize().verticalScroll(rememberScrollState())
            ) {
                Box(Modifier.fillMaxWidth().matchParentSize()) {
                    AdjustViewBoundsImage(
                        ResManager.drawable.bg_finish_page_gradient, Modifier.fillMaxWidth()
                    )
                }
                Box(Modifier.fillMaxWidth().matchParentSize()) {
                    AdjustViewBoundsImage(
                        ResManager.drawable.bg_propose_subscription_new, Modifier.fillMaxWidth()
                    )
                }

                Box(Modifier.fillMaxWidth().matchParentSize()) {
                    AdjustViewBoundsImage(
                        ResManager.drawable.bg_propose_subscription_middle_level,
                        modifier = Modifier.fillMaxWidth().alpha(0.85f)
                    )
                }

                Column(
                    Modifier.fillMaxWidth().heightIn(min = this@BoxWithConstraints.maxHeight),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    PaywallTopContent()
                    Spacer(Modifier.size(12.dp))
                    PaywallAllFeaturesContent(viewModel)
                    Spacer(Modifier.size(16.dp))

                    //ProposeScreenNewStyle()

                    val usersAmount = if (AppVariant.isFiorry()) {
                        "1M+"
                    } else if (AppVariant.isHeaven()) {
                        "300k+"
                    } else {
                        "100k+"
                    }
                    val enjoyedByText = stringResource(
                        Res.string.onboarding_propose_subscription_enjoyed_by, usersAmount
                    )


                    SubscribeDiscountMain(
                        productDetails = viewModel.products,
                        enjoyedByText = enjoyedByText,
                        weekPrice = viewModel.weekPrice,
                        paywallButtonsStyle = 1,
                        showOtherProduct = {
                            viewModel.showingOtherSubscriptions.value = true
                        },
                        callback = { },
                        isReview = false,
                        isWeekFormat = false,
                        annual12MonthsText = false,
                        cancelAnytimeNewStyle = true,
                        buySubscription = { _, _, _ ->

                        }
                    )


                    Spacer(modifier = Modifier.weight(1f))


                    ButtonPulse(
                        buttonText = stringResource(Res.string.onboarding_finish_btn),
                        colors = colorList,
                        arrowIsVisible = true,
                        withHorizontalPadding = false
                    ) {
                        println("Click on button pulse")
                        viewModel.showStripeAppleGoogle.value = true
                    }

                    SubscriptionTermsAndPrivacy(
                        isShowBottomTotalPrice = false,
                        billingManager = viewModel.billingManager,
                        selectedProductID = viewModel.selectedProductID,
                        annual12MonthsText = false,
                        onTermsClick = { },
                        onPrivacyClick = {}
                    )
                    NavigationBarPadding()
                }
            }
        }

        AnimatedVisibility(
            visible = viewModel.showingOtherSubscriptions.value,
            enter = slideInVertically(
                initialOffsetY = { fullHeight -> fullHeight },
                animationSpec = tween(durationMillis = 300)
            ),
            exit = slideOutVertically(
                targetOffsetY = { fullHeight -> fullHeight },
                animationSpec = tween(durationMillis = 300)
            )
        ) {
            Box(
                Modifier.fillMaxSize()
                    .background(MainTheme.colors.main_color_black_transparent_50)
                    .clickable(null) { viewModel.hideOtherSubscriptions() },
                contentAlignment = Alignment.BottomCenter
            ) {
                SubscribePopUpContent(
                    billingManager = viewModel.billingManager,
                    productDetails = viewModel.products.filter { !Billings.isYearSubscribe(it.productDetails.productId) },
                    btnProgress = viewModel.btnProgress,
                    selectedProduct = viewModel.selectedProduct,
                    selectedProductID = viewModel.selectedProductID,
                    weekPrice = viewModel.weekPrice,
                    mainButtonTitle = stringResource(Res.string.onboarding_finish_btn),
                    colors = colorList,
                    isNewDesign = true,
                    isNewHorizontalButtonDesign = true,
                    isBoxButtonDesign = false,
                    isShowCancelAnytime = false,
                    isShowBottomTotalPrice = false,
                    isReview = false,
                    isPropose = false,
                    isWeekFormat = true,
                    annual12MonthsText = false,
                    discountOnlyForPopularProduct = false,
                    mainButtonPulse = true,
                    mainButtonSelect = { selected -> },
                    callback = { },
                    onTermsClick = {},
                    onPrivacyClick = { },
                    dismissAllowingStateLoss = { },
                    buySubscription = { _, _, _ ->
                        viewModel.showStripeAppleGoogle.value = true
                    }
                )
            }
        }
    }

    if (viewModel.showStripeCard.value) {
        viewModel.billingManager.StripeByCardScreen(
            viewModel.selectedProductID.value,
            onPurchase = { paymentId, priceId ->
                viewModel.showStripeCard.value = false
                viewModel.buyStripeProduct(paymentId = paymentId, priceID = priceId)
            },
            onError = {
                //viewModel.errorMessage.value = it
                viewModel.showStripeCard.value = false
            })
    }

    if (viewModel.showStripeAppleGoogle.value) {
        viewModel.billingManager.StripeByAppleGoogleScreen(
            viewModel.selectedProductID.value,
            onPurchase = { paymentId, priceId ->
                viewModel.showStripeAppleGoogle.value = false
                viewModel.buyStripeProduct(paymentId = paymentId, priceID = priceId)
            }, onError = {
                println("showStripeAppleGoogle error = $it")
                //viewModel.errorMessage.value = it
                viewModel.showStripeAppleGoogle.value = false
            }
        )
    }
}

@Composable
private fun PaywallTopContent() {
    AdjustViewBoundsImage(
        ResManager.drawable.ic_propose_subscription_logo_new,
        modifier = Modifier.fillMaxWidth().fillMaxHeight(1f)
    )

    val firstPart =
        stringResource(Res.string.onboarding_propose_subscription_new_text_first)
    val secondPart =
        stringResource(Res.string.onboarding_propose_subscription_new_text_second)
    val title = stringResource(
        Res.string.onboarding_propose_subscription_new_title, firstPart, secondPart
    )

    val annotatedStringTitle = buildAnnotatedString {
        val bgColor = MainTheme.colors.subscribe_propose_fuchsia.copy(alpha = 0.4f)
        append(title)
        val firstPartStartIndex = title.indexOf(firstPart)
        val firstPartEndIndex = firstPartStartIndex + firstPart.length
        addStyle(
            style = SpanStyle(background = bgColor),
            start = firstPartStartIndex,
            end = firstPartEndIndex
        )
        val secondPartStartIndex = title.indexOf(secondPart)
        val secondPartEndIndex = secondPartStartIndex + secondPart.length
        addStyle(
            style = SpanStyle(background = bgColor),
            start = secondPartStartIndex,
            end = secondPartEndIndex
        )
    }
    BasicText(
        annotatedStringTitle,
        modifier = Modifier.fillMaxWidth(0.85f),
        style = TextStyle(
            textAlign = TextAlign.Center,
            color = MainTheme.colors.text_color_white,
            fontWeight = FontWeight.Bold,
            lineHeight = 24.sp,
        ),
        autoSize = TextAutoSize.StepBased(
            minFontSize = 12.sp,
            maxFontSize = 22.sp,
            stepSize = 1.sp
        )
    )
}

@Composable
private fun PaywallAllFeaturesContent(viewModel: PaywallScreenVM) {
    val showingAllFeatures = viewModel.showingAllFeatures.value
    Row(
        Modifier.clickable(null) {
            viewModel.showingAllFeatures.value = !viewModel.showingAllFeatures.value
        }.padding(horizontal = 16.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        val featuresText =
            if (showingAllFeatures) Res.string.subscribe_unlimited_settings_hide_text
            else Res.string.subscribe_unlimited_settings_show_text
        TextRegular(
            stringResource(featuresText), 15,
            textColor = MainTheme.colors.subscribe_propose_new_design_settings
        )

        val arrowIcon =
            if (showingAllFeatures) Res.drawable.ic_baseline_arrow_up_24
            else Res.drawable.ic_baseline_arrow_down_24
        ImageView(
            arrowIcon,
            tintColor = MainTheme.colors.subscribe_propose_new_design_settings,
            modifier = Modifier.padding(top = 1.dp).size(12.dp),
            scaleType = ContentScale.FillWidth
        )
    }

    AnimatedVisibility(
        visible = showingAllFeatures,
        enter = fadeIn() + expandVertically(),
        exit = fadeOut() + shrinkVertically()
    ) {
        Box(
            Modifier.fillMaxWidth().padding(top = 8.dp, start = 16.dp, end = 16.dp)
                .clip(RoundedCornerShape(16.dp))
        ) {
            ImageView(
                ResManager.drawable.bg_subscribe_settings,
                modifier = Modifier.matchParentSize(),
                scaleType = ContentScale.FillBounds
            )

            Column(
                Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 12.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                PaywallSettingsFeatureText(Res.string.subscribe_unlimited_read_status_top_title)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_unlimited_chats_and_profiles)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_region)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_online_status)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_new_status)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_incognito)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_read_message)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_profile_top)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_location)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_back)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_age)
                PaywallSettingsFeatureText(Res.string.subscribe_settings_interested_in_all)
            }
        }
    }
}

@Composable
fun PaywallSettingsFeatureText(res: StringResource, offerHave: Boolean = true) {
    Row(
        Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        TextRegular(
            stringResource(res), 14,
            textColor = MainTheme.colors.text_color_default,
            modifier = Modifier.weight(1f)
        )

        val icon =
            if (offerHave) Res.drawable.ic_subscribe_propose_have
            else Res.drawable.ic_subscribe_do_not_have
        ImageView(
            icon,
            modifier = Modifier.size(24.dp, 20.dp).padding(4.dp)
        )
    }
}