interface INotificationManager {

    fun init(result: () -> Unit = {})

    fun showWowNotification(result: WowResult, local: Boolean)

    fun showMessageNotification(
        result: MessageResult, local: Boolean, createRequest: Boolean = false,
        isGift: Boolean = false
    )

    fun showNotification(
        image: String?, title: String, text: String, local: Boolean, id: Int,
        chatId: String = "", isRequest: Boolean = false
    )

    fun cancelNotifications()
}