package web.views.datePicker

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.css.TextAlign
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.foundation.layout.Column
import com.varabyte.kobweb.compose.foundation.layout.Row
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.graphics.Color
import com.varabyte.kobweb.compose.ui.modifiers.background
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxWidth
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.onClick
import com.varabyte.kobweb.compose.ui.modifiers.padding
import kotlinx.datetime.LocalDate
import web.helpers.dp
import web.views.datePicker.picker.SelectorProperties
import web.theme.JsMainTheme
import web.views.JsTextView
import web.views.datePicker.picker.JsPickerDefaults

@Composable
fun JsDatePickerBottomSheet(
    modifier: Modifier = Modifier,
    title: String = "",
    doneLabel: String = "",
    startDate: LocalDate,
    rowHeight: Int = 80,
    rowCount: Int = 3,
    containerColor: Color = JsMainTheme.colors.main_color_bg_1,
    selectorProperties: SelectorProperties = JsPickerDefaults.selectorProperties(),
    onDoneClick: (snappedDate: LocalDate) -> Unit = {}
) {
    var selectedDate = startDate

    Column(modifier = modifier.fillMaxWidth().background(containerColor).onClick { event ->
        event.stopPropagation()
    }) {
        Box(modifier = Modifier.height(20.dp))
        Row(
            modifier = Modifier
                .fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            JsTextView(
                text = title,
                modifier = Modifier.weight(1f).padding(leftRight = 20.dp),
                textSize = 16,
                textColor = JsMainTheme.colors.app_main_color
            )

            JsTextView(
                text = doneLabel,
                modifier = Modifier.onClick {
                    onDoneClick(selectedDate)
                }.padding(leftRight = 16.dp),
                textAlign = TextAlign.Center,
                textSize = 16,
                textColor = JsMainTheme.colors.app_main_color
            )
        }
        Box(modifier = Modifier.height(16.dp))

        JsDatePicker(
            selectorProperties = selectorProperties,
            itemHeight = rowHeight,
            rowCount = rowCount,
            modifier = Modifier.fillMaxWidth()
                .padding(top = 14.dp, bottom = 14.dp, left = 48.dp, right = 48.dp),
            startDate = startDate,
            onDateChanged = { snappedDate -> selectedDate = snappedDate }
        )
    }
}
