@Composable
fun JsSubscribeButtons(
    productDetails: List<ProductDetails>,
    btnProgress: MutableState<Boolean>,
    selectedProduct: String,
    selectedProductID: MutableState<String>,
    startPrice: Double,
    isWeekFormat: Boolean,
    annual12MonthsText: Boolean,
    isNewHorizontalStyle: Boolean,
    isNewDesign: Boolean,
    isPropose: Boolean = false,
    isBottomDrawerFragment: Boolean = false,
    showCancelAnytime: Boolean,
    isReview: Boolean,
    callback: (Int) -> Unit = {},
    buySubscription: (Billings, Boolean, Boolean) -> Unit
) {
    Column(Modifier.fillMaxWidth().onSizeChanged { _, _ -> callback(productDetails.size) }) {
        productDetails.forEach {
            JsSubscribeButton(
                productDetails = productDetails,
                currentProduct = it,
                startPrice = startPrice,
                isWeekFormat = isWeekFormat,
                annual12MonthsText = annual12MonthsText,
                selectedProductID = selectedProductID,
                isNewHorizontalDesign = isNewHorizontalStyle,
                isNewDesign = isNewDesign,
                isPropose = isPropose,
                isPopular = selectedProduct == (it.discountDetails?.productId
                    ?: it.productDetails.productId),
                isReview = isReview,
                btnProgress = btnProgress,
                isBottomDrawerFragment = isBottomDrawerFragment,
                buySubscription = buySubscription
            )
        }

        if (showCancelAnytime) {
            Spacer(modifier = Modifier.height(20.dp))
            JsCancelAnytimeContent()
        }
    }
}

