@Composable
fun JsSubscribeButtonsContent(
    billingManager: IBillingManager,
    productDetails: List<ProductDetails>,
    btnProgress: MutableState<Boolean>,
    selectedProduct: String,
    selectedProductID: MutableState<String>,
    weekPrice: Double,
    mainButtonTitle: String,
    colors: List<Color>,
    isNewDesign: Boolean,
    isNewHorizontalButtonDesign: Boolean,
    isBoxButtonDesign: Boolean,
    isShowCancelAnytime: Boolean,
    isShowBottomTotalPrice: Boolean,
    isReview: Boolean,
    isPropose: Boolean,
    isWeekFormat: Boolean,
    annual12MonthsText: Boolean,
    discountOnlyForPopularProduct: Boolean,
    mainButtonPulse: Boolean,
    mainButtonSelect: (Boolean) -> Unit,
    callback: (Int) -> Unit = {},
    onTermsClick: () -> Unit,
    onPrivacyClick: () -> Unit,
    dismissAllowingStateLoss: () -> Unit,
    buySubscription: (Billings, Boolean, Boolean) -> Unit,
    forPopUp: Boolean = true
) {
    val colorList = colors.ifEmpty {
        listOf(
            JsMainTheme.colors.gradient_subscribe_unlim_color_start,
            JsMainTheme.colors.gradient_subscribe_unlim_color_end
        )
    }

    Column(modifier = Modifier.fillMaxWidth()) {
        Box(Modifier.fillMaxWidth().padding(horizontal = 16.dp)) {
            JsSubscribeButtonsStart(
                boxButtonDesign = isBoxButtonDesign && productDetails.size > 1,
                newHorizontalButtonDesign = isNewHorizontalButtonDesign,
                productDetails = productDetails,
                selectProduct = selectedProduct,
                selectedProductID = selectedProductID,
                startPrice = weekPrice,
                btnProgress = btnProgress,
                isReview = isReview,
                annual12MonthsText = annual12MonthsText,
                discountOnlyForPopularProduct = discountOnlyForPopularProduct,
                isNewDesign = isNewDesign,
                isPlus = false,
                isPropose = isPropose,
                isBottomDrawerFragment = true,
                isWeekFormat = isWeekFormat,
                callback = callback,
                onClick = buySubscription
            )
        }

        Spacer(modifier = Modifier.height(24.dp))

        if (isShowCancelAnytime) JsCancelAnytimeContent(bottomPadding = 30)

        if (mainButtonPulse) {
            JsButtonPulse(
                buttonText = mainButtonTitle,
                colors = colorList,
                arrowIsVisible = true
            ) {
                mainButtonSelect.invoke(forPopUp)
                dismissAllowingStateLoss.invoke()
            }
        } else {
            JsMainButtonCustom(
                text = mainButtonTitle,
                colors = colorList
            ) {
                mainButtonSelect.invoke(forPopUp)
                dismissAllowingStateLoss.invoke()
            }
        }

        JsSubscriptionTermsAndPrivacy(
            isShowBottomTotalPrice = isShowBottomTotalPrice,
            billingManager = billingManager,
            selectedProductID = selectedProductID,
            annual12MonthsText = annual12MonthsText,
            onTermsClick = onTermsClick,
            onPrivacyClick = onPrivacyClick
        )
    }
}


@Composable
fun JsSubscriptionTermsAndPrivacy(
    isShowBottomTotalPrice: Boolean,
    billingManager: IBillingManager,
    selectedProductID: MutableState<String>,
    annual12MonthsText: Boolean,
    onTermsClick: () -> Unit,
    onPrivacyClick: () -> Unit,
) {
    val terms = stringResource(Res.string.onboarding_propose_subscription_conditions)
    val privacy = stringResource(Res.string.onboarding_propose_subscription_terms)

    @Composable
    fun getTermsString(): List<AnnotatedString> {
        val termsAndPrivacyTextColor = JsMainTheme.colors.app_main_color
        val annotatedString = mutableListOf<AnnotatedString>()

        if (isShowBottomTotalPrice) {
            val productPriceDetails = billingManager.getSubscribePrice(selectedProductID.value)
            if (productPriceDetails != null) {
                val period =
                    JsSubscribeHelper.periodTitle(
                        Billings.getPeriodByProductId(selectedProductID.value),
                        annual12MonthsText = annual12MonthsText
                    )
                val priceCurrentCode = productPriceDetails.priceCurrencyCode
                val price = productPriceDetails.priceAmountMicros / 1000000.0
                val priceString = "$priceCurrentCode ${getPriceFormat(price)}"
                val totalPrice = stringResource(
                    Res.string.paywall_extra_dialog_total, priceString, period
                )
                val textColor = JsMainTheme.colors.text_color_gray
                val totalPriceModifier = Modifier.styleModifier {
                    color(textColor)
                    fontSize(12.dp)
                    fontWeight(FontWeight.Normal)
                    whiteSpace("pre-wrap")
                    //textDecorationLine(TextDecorationLine.Underline)
                    overflow(Overflow.Hidden)
                    //textAlign(TextAlign.Center)
                }
                annotatedString.add(AnnotatedString(totalPrice, totalPriceModifier))
                annotatedString.add(AnnotatedString("\n", null))
            }
        } else {
            val textColor = JsMainTheme.colors.text_color_gray
            val totalPriceModifier = Modifier.styleModifier {
                color(textColor)
                fontSize(12.dp)
                fontWeight(FontWeight.Normal)
                whiteSpace("pre-wrap")
                overflow(Overflow.Hidden)
            }
            annotatedString.add(
                AnnotatedString(
                    stringResource(Res.string.onboarding_propose_subscription_terms_and_conditions),
                    totalPriceModifier
                )
            )
            annotatedString.add(AnnotatedString("\n", null))
        }

        val termsModifier = Modifier.styleModifier {
            color(termsAndPrivacyTextColor)
            fontSize(12.dp)
            fontWeight(FontWeight.Normal)
            whiteSpace("pre-wrap")
            textDecorationLine(TextDecorationLine.Underline)
            overflow(Overflow.Hidden)
        }.onClick { onTermsClick() }
        annotatedString.add(AnnotatedString(terms, termsModifier))
        annotatedString.add(AnnotatedString("  ", null))


        val privacyModifier = Modifier.styleModifier {
            color(termsAndPrivacyTextColor)
            fontSize(12.dp)
            fontWeight(FontWeight.Normal)
            whiteSpace("pre-wrap")
            textDecorationLine(TextDecorationLine.Underline)
            overflow(Overflow.Hidden)
        }.onClick { onPrivacyClick() }
        annotatedString.add(AnnotatedString(privacy, privacyModifier))
        return annotatedString
    }

    JsAnnotatedStringsText(
        annotatedStrings = getTermsString(),
        textSize = 10,
        modifier = Modifier.fillMaxWidth().padding(vertical = 20.dp, horizontal = 16.dp),
        textAlign = TextAlign.Center
    )
}


@Composable
fun JsButtonPulse(
    buttonText: String,
    colors: List<Color>,
    arrowIsVisible: Boolean,
    durationMillis: Int = 1000,
    maxPulseHeight: Float = 70f,
    minPulseHeight: Float = 50f,
    buttonClick: () -> Unit
) {
    val infiniteTransition = rememberInfiniteTransition(label = "")
    val height = infiniteTransition.animateFloat(
        initialValue = minPulseHeight,
        targetValue = maxPulseHeight,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = ""
    )
    val alpha = infiniteTransition.animateFloat(
        initialValue = 1f, targetValue = 0f, animationSpec = infiniteRepeatable(
            animation = tween(durationMillis, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ), label = ""
    )
    Box(
        contentAlignment = Alignment.Center,
        modifier = Modifier
            .fillMaxWidth()
            .height(maxPulseHeight.dp)
    ) {

        if (colors.size <= 1) {
            val backgroundColor = colors.firstOrNull() ?: JsMainTheme.colors.app_main_color
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(height.value.dp)
                    .alpha(alpha.value)
                    .background(backgroundColor)
            )
        } else {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(height.value.dp)
                    .alpha(alpha.value)
                    .zIndex(0)
                    .gradientBackground(colors, 45)
            )
        }

        JsMainButtonCustom(
            text = buttonText, colors = colors, arrowIsVisible = arrowIsVisible
        ) { buttonClick.invoke() }
    }
}

@Composable
fun JsMainButtonCustom(
    text: String,
    colors: List<Color>,
    arrowIsVisible: Boolean = false,
    alpha: Float = 1f,
    onClick: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .alpha(alpha)
            .zIndex(1)
            .height(50.dp)
            .clickable { onClick() }, contentAlignment = Alignment.Center
    ) {
        if (colors.size <= 1) {
            val backgroundColor = colors.firstOrNull() ?: JsMainTheme.colors.app_main_color
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(backgroundColor)
            )
        } else {
            var colorsList = ""
            colors.forEachIndexed { index, color ->
                colorsList += "${color.toRgb()}${if (index != colors.lastIndex) ", " else ""}"
            }
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .gradientBackground(colors, 45)
            )
        }

        JsTextView(
            text = text,
            textColor = Colors.White,
            textSize = 16,
            fontWeight = FontWeight.Medium,
        )
        if (arrowIsVisible) {
            Box(
                modifier = Modifier.fillMaxSize().padding(end = 48.dp),
                contentAlignment = Alignment.CenterEnd
            ) {
                JsImageView(
                    Res.drawable.ic_arrow_right,
                    modifier = Modifier.fillMaxHeight().size(18.dp)
                )
            }
        }
    }
}

